insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('story-1-s1', 'story-1', 0, 'Layla lived alone in a quiet building.', 'كانت ليلى تعيش وحدها في بناية هادئة.', null, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('story-1-s2', 'story-1', 1, 'One morning, she heard noise from the empty apartment next door.', 'في صباح أحد الأيام، سمعت ضجيجًا من الشقة الفارغة المجاورة.', null, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('story-1-s3', 'story-1', 2, 'A new family was moving in.', 'كانت عائلة جديدة تنتقل للسكن هناك.', null, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('story-1-s4', 'story-1', 3, 'Layla opened her door to see what was happening.', 'فتحت ليلى بابها لترى ما يحدث.', null, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('story-1-s5', 'story-1', 4, 'A woman was carrying boxes up the stairs.', 'كانت امرأة تحمل صناديق إلى أعلى الدرج.', null, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('story-1-s6', 'story-1', 5, '"Do you need any help?" Layla asked.', 'سألت ليلى: "هل تحتاجين إلى مساعدة؟"', null, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('story-1-s7', 'story-1', 6, 'The woman smiled and said, "That would be wonderful."', 'ابتسمت المرأة وقالت: "سيكون ذلك رائعًا."', null, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('story-1-s8', 'story-1', 7, 'Her name was Noor, and she had just moved to the city.', 'كان اسمها نور، وكانت قد انتقلت للتو إلى المدينة.', null, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
