insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('story-1-s11', 'story-1', 10, '"It''s no problem at all," Layla replied.', 'أجابت ليلى: "لا مشكلة على الإطلاق."', null, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
