insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('story-1-s16', 'story-1', 15, 'Noor laughed, feeling a little less nervous.', 'ضحكت نور، وشعرت بتوتر أقل.', null, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
