insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s1', 'conversation-1', 0, 'Good evening, welcome to Star Hotel.', 'مساء الخير، أهلًا بكم في فندق النجمة.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s2', 'conversation-1', 1, 'Good evening. I have a reservation under Yasin.', 'مساء الخير. لدي حجز باسم ياسين.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s3', 'conversation-1', 2, 'One moment, let me check the system.', 'لحظة من فضلك، دعني أتحقق من النظام.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s4', 'conversation-1', 3, 'Sure, take your time.', 'بالتأكيد، خذ وقتك.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s5', 'conversation-1', 4, 'Yes, I found it. A single room for three nights.', 'نعم، وجدته. غرفة مفردة لثلاث ليالٍ.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s6', 'conversation-1', 5, 'That''s correct.', 'هذا صحيح.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s7', 'conversation-1', 6, 'Can I see your ID, please?', 'هل يمكنني رؤية هويتك من فضلك؟', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s8', 'conversation-1', 7, 'Of course, here you go.', 'بالتأكيد، تفضل.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s9', 'conversation-1', 8, 'Thank you. Your room is on the fourth floor.', 'شكرًا لك. غرفتك في الطابق الرابع.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
