insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s11', 'conversation-1', 10, 'Yes, breakfast is served from seven to ten.', 'نعم، يُقدَّم الفطور من السابعة إلى العاشرة.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
