insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s13', 'conversation-1', 12, 'Do you need help with your bags?', 'هل تحتاج مساعدة مع حقائبك؟', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
