insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s16', 'conversation-1', 15, 'Thank you. Where is the elevator?', 'شكرًا. أين المصعد؟', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s17', 'conversation-1', 16, 'It''s right around the corner.', 'إنه خلف الزاوية مباشرة.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
