insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s22', 'conversation-1', 21, 'Wonderful, thank you again.', 'رائع، شكرًا لك مجددًا.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s23', 'conversation-1', 22, 'If you need anything, just call the front desk.', 'إذا احتجت أي شيء، فقط اتصل بمكتب الاستقبال.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-1-s24', 'conversation-1', 23, 'I will, thank you.', 'سأفعل، شكرًا لك.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
