insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s1', 'conversation-2', 0, 'Good morning, how can I help you today?', 'صباح الخير، كيف يمكنني مساعدتك اليوم؟', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s2', 'conversation-2', 1, 'Good morning, doctor. I haven''t been feeling well.', 'صباح الخير يا دكتور. لم أكن أشعر بحالة جيدة.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s3', 'conversation-2', 2, 'What symptoms have you noticed?', 'ما هي الأعراض التي لاحظتها؟', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s4', 'conversation-2', 3, 'I''ve had a sore throat and a mild fever since yesterday.', 'أعاني من التهاب في الحلق وحمى خفيفة منذ الأمس.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s5', 'conversation-2', 4, 'Have you been coughing as well?', 'هل كنت تسعل أيضًا؟', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s6', 'conversation-2', 5, 'Yes, a little, mostly at night.', 'نعم، قليلًا، في الليل غالبًا.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s7', 'conversation-2', 6, 'Let me check your temperature first.', 'دعني أتحقق من درجة حرارتك أولًا.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s8', 'conversation-2', 7, 'Okay, sure.', 'حسنًا، بالتأكيد.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s9', 'conversation-2', 8, 'Your temperature is a bit high, thirty-eight degrees.', 'درجة حرارتك مرتفعة قليلًا، ثمانية وثلاثون درجة.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s10', 'conversation-2', 9, 'Is that serious?', 'هل هذا خطير؟', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s11', 'conversation-2', 10, 'Not too serious, but you should rest.', 'ليس خطيرًا جدًا، لكن يجب أن ترتاح.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s12', 'conversation-2', 11, 'Should I take any medicine?', 'هل يجب أن آخذ أي دواء؟', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s13', 'conversation-2', 12, 'I''ll prescribe something to reduce the fever.', 'سأصف لك دواءً لخفض الحرارة.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s14', 'conversation-2', 13, 'Thank you. How often should I take it?', 'شكرًا لك. كم مرة يجب أن آخذه؟', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s15', 'conversation-2', 14, 'Twice a day, after meals.', 'مرتين يوميًا، بعد الوجبات.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s16', 'conversation-2', 15, 'Should I avoid going to work?', 'هل يجب أن أتجنب الذهاب إلى العمل؟', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s17', 'conversation-2', 16, 'Yes, please rest for at least two days.', 'نعم، من فضلك ارتح لمدة يومين على الأقل.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s18', 'conversation-2', 17, 'Understood. Anything else I should do?', 'مفهوم. هل هناك شيء آخر يجب أن أفعله؟', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s19', 'conversation-2', 18, 'Drink plenty of water and warm liquids.', 'اشرب الكثير من الماء والسوائل الدافئة.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s20', 'conversation-2', 19, 'I will, thank you.', 'سأفعل ذلك، شكرًا لك.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s21', 'conversation-2', 20, 'If the fever doesn''t go down in three days, come back.', 'إذا لم تنخفض الحرارة خلال ثلاثة أيام، عد إليّ.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s22', 'conversation-2', 21, 'I understand, doctor.', 'أتفهم ذلك يا دكتور.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s23', 'conversation-2', 22, 'Do you have any allergies to medicine?', 'هل لديك حساسية من أي دواء؟', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s24', 'conversation-2', 23, 'No, none that I know of.', 'لا، لا أعرف أي حساسية.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s25', 'conversation-2', 24, 'Good, that makes this easier.', 'جيد، هذا يجعل الأمر أسهل.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s26', 'conversation-2', 25, 'Thank you for your time, doctor.', 'شكرًا لوقتك يا دكتور.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s27', 'conversation-2', 26, 'You''re welcome, take care of yourself.', 'عفوًا، اعتنِ بنفسك.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s28', 'conversation-2', 27, 'I will. Goodbye.', 'سأفعل. مع السلامة.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s29', 'conversation-2', 28, 'Goodbye, feel better soon.', 'مع السلامة، أتمنى لك الشفاء العاجل.', 'A', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, updated_at) values ('conversation-2-s30', 'conversation-2', 29, 'Thank you very much.', 'شكرًا جزيلًا لك.', 'B', now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, updated_at = now();
